+        .setDescription("Synonyms index for synonyms managed through APIs")
+        .setPrimaryIndex(SYNONYMS_INDEX_CONCRETE_NAME)
+        .setAliasName(SYNONYMS_ALIAS_NAME)
+        .setMappings(mappings())
